import React, { useState, useEffect, useCallback, useMemo } from 'react';
import api from '../services/api';
import { Container, Row, Col, Card, Carousel, Button } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';
import { 
    TextField, InputAdornment, MenuItem, Select, FormControl, 
    InputLabel, Box, IconButton, Tooltip, Typography, Skeleton,
    Fade, Grow, Zoom, Paper, Chip, Rating, Badge, Drawer,
    useMediaQuery, useTheme, Slider, FormControlLabel, Switch,
    Avatar, AvatarGroup
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import FilterListIcon from '@mui/icons-material/FilterList';
import ClearIcon from '@mui/icons-material/Clear';
import { useNavigate } from 'react-router-dom';
import Inventory2Icon from '@mui/icons-material/Inventory2';
import DesignServicesIcon from '@mui/icons-material/DesignServices';
import BuildIcon from '@mui/icons-material/Build';
import SpeedIcon from '@mui/icons-material/Speed';
import SecurityIcon from '@mui/icons-material/Security';
import SupportAgentIcon from '@mui/icons-material/SupportAgent';
import LocalOfferIcon from '@mui/icons-material/LocalOffer';
import SortIcon from '@mui/icons-material/Sort';
import ViewModuleIcon from '@mui/icons-material/ViewModule';
import ViewListIcon from '@mui/icons-material/ViewList';
import CloseIcon from '@mui/icons-material/Close';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ScheduleIcon from '@mui/icons-material/Schedule';
import PersonIcon from '@mui/icons-material/Person';
import StarIcon from '@mui/icons-material/Star';
import './Services.css';

// Service Features Component
const ServiceFeatures = () => {
    const features = [
        { icon: <SpeedIcon />, title: 'Fast Turnaround', description: '24-48 hour delivery', color: '#0046be' },
        { icon: <SecurityIcon />, title: 'Quality Guaranteed', description: 'Premium materials', color: '#ff8f00' },
        { icon: <SupportAgentIcon />, title: 'Expert Support', description: 'Dedicated team', color: '#0046be' },
        { icon: <LocalOfferIcon />, title: 'Competitive Pricing', description: 'Best value', color: '#ff8f00' }
    ];

    return (
        <Box className="service-features-section">
            <Container>
                <Row>
                    {features.map((feature, index) => (
                        <Col lg={3} md={6} xs={12} key={index} className="mb-4">
                            <Zoom in timeout={500 + index * 100}>
                                <Paper className="service-feature-card" elevation={0}>
                                    <Box className="service-feature-icon" style={{ backgroundColor: `${feature.color}15`, color: feature.color }}>
                                        {feature.icon}
                                    </Box>
                                    <Typography variant="h6" className="service-feature-title">
                                        {feature.title}
                                    </Typography>
                                    <Typography variant="body2" className="service-feature-description">
                                        {feature.description}
                                    </Typography>
                                </Paper>
                            </Zoom>
                        </Col>
                    ))}
                </Row>
            </Container>
        </Box>
    );
};

// Service Process Component
const ServiceProcess = () => {
    const steps = [
        { icon: <PersonIcon />, title: 'Consultation', description: 'Discuss your requirements' },
        { icon: <DesignServicesIcon />, title: 'Design & Quote', description: 'Get a custom quote' },
        { icon: <CheckCircleIcon />, title: 'Approval', description: 'Review and approve' },
        { icon: <BuildIcon />, title: 'Production', description: 'Quality printing' },
        { icon: <ScheduleIcon />, title: 'Delivery', description: 'Fast shipping' }
    ];

    return (
        <Box className="service-process-section">
            <Container>
                <Typography variant="h3" className="process-title">
                    How It Works
                </Typography>
                <Typography variant="body1" className="process-subtitle">
                    Simple steps to get your printing services
                </Typography>
                <Row className="process-steps">
                    {steps.map((step, index) => (
                        <Col lg={12/5} md={6} xs={12} key={index} className="step-col">
                            <Grow in timeout={500 + index * 100}>
                                <Box className="process-step">
                                    <Box className="step-number">{index + 1}</Box>
                                    <Box className="step-icon">{step.icon}</Box>
                                    <Typography variant="h6" className="step-title">
                                        {step.title}
                                    </Typography>
                                    <Typography variant="body2" className="step-description">
                                        {step.description}
                                    </Typography>
                                    {index < steps.length - 1 && (
                                        <Box className="step-connector" />
                                    )}
                                </Box>
                            </Grow>
                        </Col>
                    ))}
                </Row>
            </Container>
        </Box>
    );
};

// Service Card Component
const ServiceCard = ({ device, onViewDetails, onOrderNow }) => {
    const [isHovered, setIsHovered] = useState(false);
    const [currentImageIndex, setCurrentImageIndex] = useState(0);
    
    const images = [device.image1, device.image2, device.image3].filter(Boolean);
    
    useEffect(() => {
        if (!isHovered || images.length <= 1) return;
        const interval = setInterval(() => {
            setCurrentImageIndex((prev) => (prev + 1) % images.length);
        }, 3000);
        return () => clearInterval(interval);
    }, [isHovered, images.length]);

    const getDeliveryTime = () => {
        const times = ['24 hours', '48 hours', '3-5 days', 'Express available'];
        return times[Math.floor(Math.random() * times.length)];
    };

    return (
        <Grow in timeout={300}>
            <Card 
                className="service-card"
                onMouseEnter={() => setIsHovered(true)}
                onMouseLeave={() => setIsHovered(false)}
            >
                <Box className="service-card-image-wrapper">
                    <div className="service-card-image-container">
                        <img 
                            src={images[currentImageIndex] || '/placeholder-service.jpg'} 
                            alt={device.name}
                            className="service-card-image"
                        />
                        {images.length > 1 && (
                            <Box className="service-image-nav">
                                {images.map((_, idx) => (
                                    <span 
                                        key={idx}
                                        className={`service-nav-dot ${currentImageIndex === idx ? 'active' : ''}`}
                                        onClick={() => setCurrentImageIndex(idx)}
                                    />
                                ))}
                            </Box>
                        )}
                    </div>
                    
                    {device.isPopular && (
                        <Chip 
                            icon={<StarIcon />} 
                            label="Popular" 
                            size="small" 
                            className="popular-badge"
                        />
                    )}
                    
                    <Fade in={isHovered}>
                        <Box className="service-card-overlay">
                            <Tooltip title="Quick View">
                                <IconButton className="service-overlay-btn" onClick={() => onViewDetails(device.id)}>
                                    <DesignServicesIcon />
                                </IconButton>
                            </Tooltip>
                            <Tooltip title="Order Now">
                                <IconButton className="service-overlay-btn" onClick={() => onOrderNow(device.id)}>
                                    <BuildIcon />
                                </IconButton>
                            </Tooltip>
                        </Box>
                    </Fade>
                </Box>
                
                <Card.Body className="service-card-body">
                    <Box className="service-card-header">
                        <Typography className="service-card-title">
                            {device.name}
                        </Typography>
                        <Chip 
                            label={`Delivery: ${getDeliveryTime()}`}
                            size="small"
                            className="delivery-chip"
                            icon={<ScheduleIcon />}
                        />
                    </Box>
                    
                    <Typography className="service-card-description">
                        {device.description?.substring(0, 100)}...
                    </Typography>
                    
                    <Box className="service-features-list">
                        <Chip label="Premium Quality" size="small" className="service-feature-chip" />
                        <Chip label="Custom Design" size="small" className="service-feature-chip" />
                        <Chip label="Free Consultation" size="small" className="service-feature-chip" />
                    </Box>
                    
                    <Box className="service-price-container">
                        <Typography className="service-price-label">Starting from</Typography>
                        <Typography className="service-price">
                            ETB {parseFloat(device.price).toLocaleString()}
                        </Typography>
                    </Box>
                    
                    <Box className="service-card-actions">
                        <Button 
                            variant="outlined"
                            className="service-details-btn"
                            onClick={() => onViewDetails(device.id)}
                        >
                            View Details
                        </Button>
                        <Button 
                            variant="contained"
                            className="service-order-btn"
                            onClick={() => onOrderNow(device.id)}
                        >
                            Get Quote
                        </Button>
                    </Box>
                </Card.Body>
            </Card>
        </Grow>
    );
};

const Services = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const isTablet = useMediaQuery(theme.breakpoints.down('md'));
    const [devices, setDevices] = useState([]);
    const [categories, setCategories] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredDevices, setFilteredDevices] = useState([]);
    const [priceRange, setPriceRange] = useState([0, 10000]);
    const [categoryFilter, setCategoryFilter] = useState('');
    const [typeFilter, setTypeFilter] = useState(''); 
    const [sortBy, setSortBy] = useState('newest');
    const [showFilters, setShowFilters] = useState(!isMobile);
    const [loading, setLoading] = useState(true);
    const [viewMode, setViewMode] = useState('grid');
    const [showMobileFilters, setShowMobileFilters] = useState(false);
    const [showScrollTop, setShowScrollTop] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const handleScroll = () => {
            setShowScrollTop(window.scrollY > 500);
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const scrollToTop = () => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    useEffect(() => {
        fetchDevices();
        fetchCategories();
    }, []);

    useEffect(() => {
        filterAndSortDevices();
    }, [searchQuery, priceRange, categoryFilter, typeFilter, sortBy, devices]);

    const fetchDevices = () => {
        setLoading(true);
        api.get('devices/?page=Service')
            .then(response => {
                let services = response.data;
                services = services.map(service => ({
                    ...service,
                    isPopular: Math.random() > 0.7,
                    rating: (Math.random() * 2 + 3).toFixed(1),
                    reviewCount: Math.floor(Math.random() * 50) + 5
                }));
                setDevices(services);
                setLoading(false);
            })
            .catch(error => {
                console.error('Error fetching services:', error);
                api.get('devices/')
                    .then(response => {
                        let services = response.data.filter(d => d.page === 'Service');
                        services = services.map(service => ({
                            ...service,
                            isPopular: Math.random() > 0.7,
                            rating: (Math.random() * 2 + 3).toFixed(1),
                            reviewCount: Math.floor(Math.random() * 50) + 5
                        }));
                        setDevices(services);
                        setLoading(false);
                    });
            });
    };

    const fetchCategories = () => {
        api.get('categories/')
            .then(response => setCategories(response.data))
            .catch(error => console.error('Error fetching categories:', error));
    };

    const filterAndSortDevices = () => {
        let filtered = devices.filter(device => device.page === 'Service');

        if (searchQuery) {
            filtered = filtered.filter(device =>
                device.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                device.description.toLowerCase().includes(searchQuery.toLowerCase())
            );
        }

        if (priceRange[1] < 10000) {
            filtered = filtered.filter(device => device.price >= priceRange[0] && device.price <= priceRange[1]);
        }

        if (categoryFilter) {
            filtered = filtered.filter(device => device.category === parseInt(categoryFilter));
        }

        if (typeFilter) {
            filtered = filtered.filter(device => device.type === typeFilter);
        }

        switch (sortBy) {
            case 'price-low':
                filtered.sort((a, b) => a.price - b.price);
                break;
            case 'price-high':
                filtered.sort((a, b) => b.price - a.price);
                break;
            case 'rating':
                filtered.sort((a, b) => (b.rating || 0) - (a.rating || 0));
                break;
            case 'popular':
                filtered.sort((a, b) => (b.isPopular ? 1 : 0) - (a.isPopular ? 1 : 0));
                break;
            default:
                filtered.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
        }

        setFilteredDevices(filtered);
    };

    const handleViewDetails = (id) => {
        navigate(`/device/${id}`);
    };

    const handleOrderNow = (id) => {
        navigate(`/order/${id}`);
    };

    const renderSkeletons = () => Array(6).fill(0).map((_, index) => (
        <Col lg={4} md={6} xs={12} key={index} className="mb-4">
            <Card className="service-card-skeleton">
                <Skeleton variant="rectangular" height={250} animation="wave" />
                <Card.Body>
                    <Skeleton variant="text" width="70%" height={30} />
                    <Skeleton variant="text" width="90%" />
                    <Skeleton variant="text" width="60%" />
                    <Box sx={{ mt: 2 }}>
                        <Skeleton variant="rectangular" height={40} />
                    </Box>
                </Card.Body>
            </Card>
        </Col>
    ));

    const FilterContent = () => (
        <Box className="service-filter-content">
            <Box className="service-filter-header">
                <Typography variant="h6" className="service-filter-title">Filters</Typography>
                {isMobile && (
                    <IconButton onClick={() => setShowMobileFilters(false)}>
                        <CloseIcon />
                    </IconButton>
                )}
            </Box>
            
            <Box className="service-filter-group">
                <Typography variant="subtitle2" className="service-filter-label">Search</Typography>
                <TextField
                    variant="outlined"
                    placeholder="Search services..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    fullWidth
                    size="small"
                    className="service-filter-search"
                    InputProps={{
                        endAdornment: searchQuery && (
                            <InputAdornment position="end">
                                <IconButton onClick={() => setSearchQuery('')} size="small">
                                    <ClearIcon />
                                </IconButton>
                            </InputAdornment>
                        )
                    }}
                />
            </Box>
            
            <Box className="service-filter-group">
                <Typography variant="subtitle2" className="service-filter-label">Categories</Typography>
                <FormControl fullWidth size="small">
                    <Select 
                        value={categoryFilter} 
                        onChange={(e) => setCategoryFilter(e.target.value)}
                        className="service-filter-select"
                    >
                        <MenuItem value="">All Categories</MenuItem>
                        {categories.map(c => (
                            <MenuItem key={c.id} value={c.id}>
                                {c.name}
                            </MenuItem>
                        ))}
                    </Select>
                </FormControl>
            </Box>
            
            <Box className="service-filter-group">
                <Typography variant="subtitle2" className="service-filter-label">Price Range (ETB)</Typography>
                <Slider
                    value={priceRange}
                    onChange={(e, newValue) => setPriceRange(newValue)}
                    valueLabelDisplay="auto"
                    min={0}
                    max={10000}
                    className="service-price-slider"
                />
                <Box className="service-price-range-values">
                    <Typography variant="caption">ETB {priceRange[0].toLocaleString()}</Typography>
                    <Typography variant="caption">ETB {priceRange[1].toLocaleString()}</Typography>
                </Box>
            </Box>
            
            <Box className="service-filter-group">
                <Typography variant="subtitle2" className="service-filter-label">Sort By</Typography>
                <FormControl fullWidth size="small">
                    <Select 
                        value={sortBy} 
                        onChange={(e) => setSortBy(e.target.value)}
                        className="service-filter-select"
                    >
                        <MenuItem value="newest">Newest First</MenuItem>
                        <MenuItem value="price-low">Price: Low to High</MenuItem>
                        <MenuItem value="price-high">Price: High to Low</MenuItem>
                        <MenuItem value="rating">Top Rated</MenuItem>
                        <MenuItem value="popular">Most Popular</MenuItem>
                    </Select>
                </FormControl>
            </Box>
            
            <Button 
                variant="outlined" 
                fullWidth
                onClick={() => {
                    setSearchQuery('');
                    setCategoryFilter('');
                    setPriceRange([0, 10000]);
                    setSortBy('newest');
                    setTypeFilter('');
                }}
                className="service-reset-filters"
            >
                Reset All Filters
            </Button>
        </Box>
    );

    const getGridCols = () => {
        if (viewMode === 'list') return 1;
        if (isMobile) return 1;
        if (isTablet) return 2;
        return 3;
    };

    return (
        <Box className="services-page">
            {/* Hero Section */}
            <Box className="services-hero">
                <Container>
                    <Fade in timeout={800}>
                        <Box className="services-hero-content">
                            <Typography variant="overline" className="services-hero-overline">
                                Professional Printing Services
                            </Typography>
                            <Typography variant="h1" className="services-hero-title">
                                Our Services
                            </Typography>
                            <Typography variant="h5" className="services-hero-subtitle">
                                Premium printing solutions tailored to your needs
                            </Typography>
                            <Typography variant="body1" className="services-hero-description">
                                From business cards to billboards, we deliver excellence in every print
                            </Typography>
                        </Box>
                    </Fade>
                </Container>
                <Box className="services-hero-bg" />
            </Box>

            {/* Features Section */}
            <ServiceFeatures />

            {/* Process Section */}
            <ServiceProcess />

            {/* Main Content */}
            <Container className="services-main">
                {/* Search and Filter Bar */}
                <Paper className="services-search-bar" elevation={0}>
                    <Row className="align-items-center">
                        <Col md={5} lg={6}>
                            <TextField
                                variant="outlined"
                                placeholder="Search services..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                fullWidth
                                className="services-search-input"
                                InputProps={{
                                    startAdornment: <InputAdornment position="start"><SearchIcon /></InputAdornment>,
                                    endAdornment: searchQuery && (
                                        <InputAdornment position="end">
                                            <IconButton onClick={() => setSearchQuery('')} size="small">
                                                <ClearIcon />
                                            </IconButton>
                                        </InputAdornment>
                                    )
                                }}
                            />
                        </Col>
                        
                        <Col md={3} lg={3}>
                            <FormControl fullWidth size="small" className="services-sort-select">
                                <InputLabel>Sort By</InputLabel>
                                <Select 
                                    value={sortBy} 
                                    onChange={(e) => setSortBy(e.target.value)}
                                    label="Sort By"
                                    startAdornment={<SortIcon sx={{ mr: 1 }} />}
                                >
                                    <MenuItem value="newest">Newest First</MenuItem>
                                    <MenuItem value="price-low">Price: Low to High</MenuItem>
                                    <MenuItem value="price-high">Price: High to Low</MenuItem>
                                    <MenuItem value="rating">Top Rated</MenuItem>
                                    <MenuItem value="popular">Most Popular</MenuItem>
                                </Select>
                            </FormControl>
                        </Col>
                        
                        <Col md={2} lg={2}>
                            <Box className="services-view-toggle">
                                <Tooltip title="Grid View">
                                    <IconButton 
                                        className={viewMode === 'grid' ? 'active' : ''}
                                        onClick={() => setViewMode('grid')}
                                    >
                                        <ViewModuleIcon />
                                    </IconButton>
                                </Tooltip>
                                <Tooltip title="List View">
                                    <IconButton 
                                        className={viewMode === 'list' ? 'active' : ''}
                                        onClick={() => setViewMode('list')}
                                    >
                                        <ViewListIcon />
                                    </IconButton>
                                </Tooltip>
                            </Box>
                        </Col>
                        
                        <Col md={2} lg={1}>
                            {isMobile ? (
                                <Button 
                                    variant="outlined" 
                                    fullWidth
                                    onClick={() => setShowMobileFilters(true)}
                                    startIcon={<FilterListIcon />}
                                    className="services-filter-btn-mobile"
                                >
                                    Filter
                                </Button>
                            ) : (
                                <Button 
                                    variant="outlined" 
                                    fullWidth
                                    onClick={() => setShowFilters(!showFilters)}
                                    startIcon={<FilterListIcon />}
                                    className="services-filter-btn"
                                >
                                    {showFilters ? 'Hide' : 'Filters'}
                                </Button>
                            )}
                        </Col>
                    </Row>
                </Paper>

                {/* Desktop Filters */}
                {!isMobile && showFilters && (
                    <Paper className="services-filters-panel" elevation={0}>
                        <FilterContent />
                    </Paper>
                )}

                {/* Mobile Filters Drawer */}
                <Drawer
                    anchor="right"
                    open={showMobileFilters}
                    onClose={() => setShowMobileFilters(false)}
                    className="services-mobile-drawer"
                >
                    <FilterContent />
                </Drawer>

                {/* Results Stats */}
                <Box className="services-results-stats">
                    <Typography variant="body2" className="services-stats-text">
                        Showing <strong>{filteredDevices.length}</strong> of <strong>{devices.length}</strong> services
                    </Typography>
                    {searchQuery && (
                        <Chip 
                            label={`Search: "${searchQuery}"`} 
                            size="small"
                            onDelete={() => setSearchQuery('')}
                            className="services-search-chip"
                        />
                    )}
                </Box>

                {/* Services Grid */}
                <Row className={`services-grid ${viewMode === 'list' ? 'list-view' : ''}`}>
                    {loading ? (
                        renderSkeletons()
                    ) : filteredDevices.length > 0 ? (
                        filteredDevices.map(device => (
                            <Col lg={getGridCols()} md={6} sm={12} xs={12} key={device.id} className="mb-4">
                                <ServiceCard 
                                    device={device}
                                    onViewDetails={handleViewDetails}
                                    onOrderNow={handleOrderNow}
                                />
                            </Col>
                        ))
                    ) : (
                        <Box className="services-empty-state">
                            <DesignServicesIcon className="services-empty-icon" />
                            <Typography variant="h5" className="services-empty-title">
                                No services found
                            </Typography>
                            <Typography variant="body1" className="services-empty-message">
                                Try adjusting your search or filter criteria
                            </Typography>
                            <Button 
                                variant="contained" 
                                onClick={() => {
                                    setSearchQuery('');
                                    setCategoryFilter('');
                                    setPriceRange([0, 10000]);
                                    setSortBy('newest');
                                }}
                                className="services-empty-btn"
                            >
                                Clear all filters
                            </Button>
                        </Box>
                    )}
                </Row>
            </Container>

            {/* Scroll to Top Button */}
            <Fade in={showScrollTop}>
                <IconButton className="services-scroll-top" onClick={scrollToTop}>
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M12 4L12 20M12 4L18 10M12 4L6 10" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                </IconButton>
            </Fade>
        </Box>
    );
};

export default Services;