import React from 'react';
import { 
    Container, Typography, Box, Paper, Grid, 
    Divider, Stack, Avatar, useTheme 
} from '@mui/material';
import { 
    Brush, Print, Campaign, Stars, 
    Public, Speed, WorkspacePremium 
} from '@mui/icons-material';

const AboutUs = () => {
    const theme = useTheme();

    const services = [
        { icon: <Print fontSize="large" />, title: "Precision Printing", desc: "Industrial-grade T-shirt and material printing using eco-friendly, long-lasting inks." },
        { icon: <Brush fontSize="large" />, title: "Graphic Design", desc: "International award-winning design aesthetics tailored to your brand identity." },
        { icon: <Campaign fontSize="large" />, title: "Ad Solutions", desc: "Strategic advertising campaigns designed to maximize ROI and market reach." },
    ];

    const stats = [
        { label: "Client Satisfaction", value: "99%" },
        { label: "Global Projects", value: "500+" },
        { label: "Design Iterations", value: "Unlimited" },
    ];

    return (
        <Container maxWidth="lg" sx={{ py: 8 }}>
            {/* Hero Section */}
            <Box textAlign="center" mb={10}>
                <Typography 
                    variant="overline" 
                    sx={{ color: '#1A237E', fontWeight: 800, letterSpacing: 2 }}
                >
                    WELCOME TO PARROT ADVERT
                </Typography>
                <Typography 
                    variant="h2" 
                    sx={{ 
                        fontWeight: 900, 
                        background: 'linear-gradient(45deg, #1A237E 30%, #FFD700 90%)',
                        WebkitBackgroundClip: 'text',
                        WebkitTextFillColor: 'transparent',
                        mb: 3
                    }}
                >
                    Bringing Visions to Life.
                </Typography>
                <Typography variant="h6" color="textSecondary" sx={{ maxWidth: 700, mx: 'auto', lineHeight: 1.6 }}>
                    Parrot Advert is a premier creative powerhouse specializing in high-fidelity printing, 
                    bespoke graphic design, and globally-recognized advertising strategies.
                </Typography>
            </Box>

            <Grid container spacing={6} alignItems="center">
                {/* Visual Content */}
                <Grid item xs={12} md={6}>
                    <Paper 
                        elevation={0} 
                        sx={{ 
                            p: 4, 
                            bgcolor: '#f8f9fa', 
                            borderRadius: 4, 
                            borderLeft: '10px solid #FFD700' 
                        }}
                    >
                        <Typography variant="h4" fontWeight={700} gutterBottom color="#1A237E">
                            Our International Standards
                        </Typography>
                        <Typography variant="body1" paragraph color="textSecondary">
                            At Parrot Advert, we don't just print; we communicate. Leveraging international design 
                            trends from tech hubs across Europe and the US, we bring a modern, minimalist, 
                            and high-impact aesthetic to the Ethiopian market.
                        </Typography>
                        <Typography variant="body1" paragraph color="textSecondary">
                            Our workflow follows the <strong>ISO Quality Management</strong> guidelines, ensuring that 
                            every T-shirt, banner, or digital campaign meets global durability and color accuracy standards.
                        </Typography>
                    </Paper>
                </Grid>

                {/* Services Grid */}
                <Grid item xs={12} md={6}>
                    <Stack spacing={3}>
                        {services.map((service, index) => (
                            <Box key={index} display="flex" gap={3} alignItems="flex-start">
                                <Avatar sx={{ bgcolor: '#1A237E', color: '#FFD700', width: 56, height: 56 }}>
                                    {service.icon}
                                </Avatar>
                                <Box>
                                    <Typography variant="h6" fontWeight={700}>{service.title}</Typography>
                                    <Typography variant="body2" color="textSecondary">{service.desc}</Typography>
                                </Box>
                            </Box>
                        ))}
                    </Stack>
                </Grid>
            </Grid>

            {/* Values & Experience Section */}
            <Box mt={12} textAlign="center">
                <Typography variant="h4" fontWeight={800} mb={6}>Why Global Brands Trust Us</Typography>
                <Grid container spacing={4}>
                    <Grid item xs={12} sm={4}>
                        <WorkspacePremium sx={{ fontSize: 50, color: '#FFD700', mb: 2 }} />
                        <Typography variant="h6">Premium Quality</Typography>
                        <Typography variant="body2" color="textSecondary">We use cutting-edge Roland and Mimaki technology for unmatched precision.</Typography>
                    </Grid>
                    <Grid item xs={12} sm={4}>
                        <Speed sx={{ fontSize: 50, color: '#FFD700', mb: 2 }} />
                        <Typography variant="h6">Agile Delivery</Typography>
                        <Typography variant="body2" color="textSecondary">Rapid turnaround times synchronized with global supply chain standards.</Typography>
                    </Grid>
                    <Grid item xs={12} sm={4}>
                        <Public sx={{ fontSize: 50, color: '#FFD700', mb: 2 }} />
                        <Typography variant="h6">Local Insight, Global Reach</Typography>
                        <Typography variant="body2" color="textSecondary">Understanding local culture while applying international design psychology.</Typography>
                    </Grid>
                </Grid>
            </Box>

            {/* Stats Section */}
            <Paper 
                elevation={0} 
                sx={{ 
                    mt: 10, 
                    p: 6, 
                    borderRadius: 4, 
                    background: '#1A237E', 
                    color: 'white' 
                }}
            >
                <Grid container justifyContent="center" spacing={4}>
                    {stats.map((stat, i) => (
                        <Grid item xs={6} md={3} key={i} textAlign="center">
                            <Typography variant="h3" fontWeight={900} sx={{ color: '#FFD700' }}>{stat.value}</Typography>
                            <Typography variant="button" sx={{ opacity: 0.8, letterSpacing: 1 }}>{stat.label}</Typography>
                        </Grid>
                    ))}
                </Grid>
            </Paper>
        </Container>
    );
};

export default AboutUs;