import React from 'react';
import { Box, Typography, Link, Container, Stack, IconButton } from '@mui/material';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPhone, faEnvelope, faMapMarkerAlt } from '@fortawesome/free-solid-svg-icons';
import HomeIcon from '@mui/icons-material/Home';
import InfoIcon from '@mui/icons-material/Info';
import ContactMailIcon from '@mui/icons-material/ContactMail';
import FacebookIcon from '@mui/icons-material/Facebook';
import TwitterIcon from '@mui/icons-material/Twitter';
import InstagramIcon from '@mui/icons-material/Instagram';
import TelegramIcon from '@mui/icons-material/Telegram';
import { Link as RouterLink } from 'react-router-dom';

const Footer = () => {
    const currentYear = new Date().getFullYear();

    return (
        <Box 
            component="footer" 
            sx={{ 
                mt: 8,
                background: 'linear-gradient(135deg, #2b2d42 0%, #1a1a2e 100%)',
                color: 'white',
                position: 'relative',
                overflow: 'hidden'
            }}
        >
            {/* Decorative elements */}
            <Box
                sx={{
                    position: 'absolute',
                    top: -100,
                    right: -100,
                    width: 300,
                    height: 300,
                    borderRadius: '50%',
                    background: 'rgba(67, 97, 238, 0.1)'
                }}
            />
            <Box
                sx={{
                    position: 'absolute',
                    bottom: -50,
                    left: -50,
                    width: 200,
                    height: 200,
                    borderRadius: '50%',
                    background: 'rgba(247, 37, 133, 0.1)'
                }}
            />

            <Container maxWidth="lg" sx={{ py: 6, position: 'relative', zIndex: 1 }}>
                <Stack 
                    direction={{ xs: 'column', md: 'row' }} 
                    spacing={4}
                    justifyContent="space-between"
                    alignItems={{ xs: 'center', md: 'flex-start' }}
                >
                    {/* Company Info */}
                    <Box sx={{ textAlign: { xs: 'center', md: 'left' }, maxWidth: 300 }}>
                        <Typography 
                            variant="h5" 
                            sx={{ 
                                fontWeight: 700, 
                                mb: 2,
                                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                                WebkitBackgroundClip: 'text',
                                WebkitTextFillColor: 'transparent'
                            }}
                        >
                            Parrot Advert
                        </Typography>
                        <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)', mb: 2 }}>
                            Your trusted source for quality design and prints. 
                            We provide the best items at competitive prices.
                        </Typography>
                        <Stack direction="row" spacing={1} justifyContent={{ xs: 'center', md: 'flex-start' }}>
                            <IconButton 
                                size="small" 
                                sx={{ 
                                    color: 'white',
                                    backgroundColor: 'rgba(255,255,255,0.1)',
                                    '&:hover': { backgroundColor: '#4361ee' }
                                }}
                            >
                                <FacebookIcon />
                            </IconButton>
                            <IconButton 
                                size="small" 
                                sx={{ 
                                    color: 'white',
                                    backgroundColor: 'rgba(255,255,255,0.1)',
                                    '&:hover': { backgroundColor: '#4361ee' }
                                }}
                            >
                                <TwitterIcon />
                            </IconButton>
                            <IconButton 
                                size="small" 
                                sx={{ 
                                    color: 'white',
                                    backgroundColor: 'rgba(255,255,255,0.1)',
                                    '&:hover': { backgroundColor: '#4361ee' }
                                }}
                            >
                                <InstagramIcon />
                            </IconButton>
                            <IconButton 
                                size="small" 
                                sx={{ 
                                    color: 'white',
                                    backgroundColor: 'rgba(255,255,255,0.1)',
                                    '&:hover': { backgroundColor: '#4361ee' }
                                }}
                            >
                                <TelegramIcon />
                            </IconButton>
                        </Stack>
                    </Box>

                    {/* Quick Links */}
                    <Box sx={{ textAlign: { xs: 'center', md: 'left' } }}>
                        <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
                            Quick Links
                        </Typography>
                        <Stack spacing={1}>
                            <Link 
                                component={RouterLink} 
                                to="/" 
                                sx={{ 
                                    color: 'rgba(255,255,255,0.7)', 
                                    textDecoration: 'none',
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: 1,
                                    '&:hover': { color: '#4361ee' }
                                }}
                            >
                                <HomeIcon sx={{ fontSize: 18 }} />
                                Home
                            </Link>
                            <Link 
                                component={RouterLink} 
                                to="/about-us" 
                                sx={{ 
                                    color: 'rgba(255,255,255,0.7)', 
                                    textDecoration: 'none',
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: 1,
                                    '&:hover': { color: '#4361ee' }
                                }}
                            >
                                <InfoIcon sx={{ fontSize: 18 }} />
                                About Us
                            </Link>
                            <Link 
                                component={RouterLink} 
                                to="/contact-us" 
                                sx={{ 
                                    color: 'rgba(255,255,255,0.7)', 
                                    textDecoration: 'none',
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: 1,
                                    '&:hover': { color: '#4361ee' }
                                }}
                            >
                                <ContactMailIcon sx={{ fontSize: 18 }} />
                                Contact Us
                            </Link>
                        </Stack>
                    </Box>

                    {/* Contact Info */}
                    <Box sx={{ textAlign: { xs: 'center', md: 'left' } }}>
                        <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
                            Contact Info
                        </Typography>
                        <Stack spacing={1.5}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, justifyContent: { xs: 'center', md: 'flex-start' } }}>
                                <FontAwesomeIcon icon={faPhone} style={{ color: '#4361ee' }} />
<Link href="tel:+251937406498" sx={{ color: 'rgba(255,255,255,0.7)', textDecoration: 'none', '&:hover': { color: '#4361ee' } }}>
                                    +251 93 740 6498
                                </Link>
                            </Box>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, justifyContent: { xs: 'center', md: 'flex-start' } }}>
                                <FontAwesomeIcon icon={faEnvelope} style={{ color: '#4361ee' }} />
<Link href="mailto:info@getparrot.com" sx={{ color: 'rgba(255,255,255,0.7)', textDecoration: 'none', '&:hover': { color: '#4361ee' } }}>
                                    info@getparrot.com
                                </Link>
                            </Box>
                            <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, justifyContent: { xs: 'center', md: 'flex-start' } }}>
                                <FontAwesomeIcon icon={faMapMarkerAlt} style={{ color: '#4361ee', marginTop: 4 }} />
                                <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                                    Bahirdar, Ethiopia
                                </Typography>
                            </Box>
                        </Stack>
                    </Box>
                </Stack>

                {/* Divider */}
                <Box 
                    sx={{ 
                        my: 4, 
                        height: 1, 
                        backgroundColor: 'rgba(255,255,255,0.1)' 
                    }} 
                />

                {/* Bottom Section */}
                <Stack 
                    direction={{ xs: 'column', md: 'row' }} 
                    justifyContent="space-between" 
                    alignItems="center"
                    spacing={2}
                >
                    <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                        © {currentYear} Parrot Advert. All rights reserved.
                    </Typography>
                    <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                         developed by: <strong style={{ color: '#4361ee' }}>Zemenu.Tadele21@gmail.com</strong>
                    </Typography>
                </Stack>
            </Container>
        </Box>
    );
};

export default Footer;
