import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import Collapse from '@mui/material/Collapse';
// MUI Components
import { 
    Container, Grid, Card, CardContent, Chip, 
    Button, TextField, MenuItem, Select, 
    FormControl, InputLabel, Box, Stack, 
    Typography, Skeleton, InputAdornment,
    Dialog, DialogTitle, DialogContent, DialogActions,
    IconButton, Divider, Alert, AlertTitle,
    Fade, Grow, Zoom, Paper, Badge, SpeedDial, SpeedDialAction,
    useMediaQuery, useTheme, Breadcrumbs, Link, Rating
} from '@mui/material';

// MUI Icons
import SearchIcon from '@mui/icons-material/Search';
import FilterListIcon from '@mui/icons-material/FilterList';
import CloseIcon from '@mui/icons-material/Close';
import TelegramIcon from '@mui/icons-material/Telegram';
import FacebookIcon from '@mui/icons-material/Facebook';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import InstagramIcon from '@mui/icons-material/Instagram';
import FormatQuoteIcon from '@mui/icons-material/FormatQuote';
import ErrorIcon from '@mui/icons-material/Error';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';
import VisibilityIcon from '@mui/icons-material/Visibility';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import LocalOfferIcon from '@mui/icons-material/LocalOffer';
import SpeedIcon from '@mui/icons-material/Speed';
import SecurityIcon from '@mui/icons-material/Security';
import SupportAgentIcon from '@mui/icons-material/SupportAgent';
import SortIcon from '@mui/icons-material/Sort';
import ViewModuleIcon from '@mui/icons-material/ViewModule';
import ViewListIcon from '@mui/icons-material/ViewList';
import KeyboardArrowUpIcon from '@mui/icons-material/KeyboardArrowUp';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';

// Project Imports
import api, { getDevicesByPage } from '../services/api';
import BlinkingDiscountBadge from './BlinkingDiscountBadge';
import './DeviceList.css';

// Fallback categories
const FALLBACK_CATEGORIES = [
    { id: 1, name: "Printers", icon: "🖨️", count: 24 },
    { id: 2, name: "Scanners", icon: "📠", count: 12 },
    { id: 3, name: "Copiers", icon: "📄", count: 18 },
    { id: 4, name: "Accessories", icon: "🔌", count: 36 },
    { id: 5, name: "Supplies", icon: "📦", count: 42 }
];

// Sort options
const sortOptions = [
    { value: 'newest', label: 'Newest First', icon: '🆕' },
    { value: 'price_asc', label: 'Price: Low to High', icon: '💰' },
    { value: 'price_desc', label: 'Price: High to Low', icon: '💎' },
    { value: 'popular', label: 'Most Popular', icon: '⭐' },
    { value: 'name_asc', label: 'Name: A to Z', icon: '📝' }
];

const DeviceImageSlider = ({ device }) => {
    const images = [device.image1, device.image2, device.image3].filter(img => img != null);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [isHovered, setIsHovered] = useState(false);

    useEffect(() => {
        if (images.length <= 1 || !isHovered) return;
        const interval = setInterval(() => {
            setCurrentIndex((prev) => (prev + 1) % images.length);
        }, 3000);
        return () => clearInterval(interval);
    }, [images, isHovered]);

    return (
        <Box 
            className="card-img-container"
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
        >
            <img 
                src={images[currentIndex] || '/placeholder-electronics.png'} 
                alt={device.name} 
                className="card-img-top"
            />
            {images.length > 1 && (
                <Box className="image-counter">
                    <Typography variant="caption">
                        {currentIndex + 1} / {images.length}
                    </Typography>
                </Box>
            )}
            {device.isNew && (
                <Chip label="NEW" size="small" className="new-badge" />
            )}
        </Box>
    );
};

const QuoteModal = ({ open, onClose }) => {
    const socialLinks = {
        telegram: "https://t.me/yourprintingsolution",
        facebook: "https://facebook.com/yourprintingsolution",
        whatsapp: "https://wa.me/251900000000?text=I%27m%20interested%20in%20getting%20a%20quote%20for%20printing%20services",
        instagram: "https://instagram.com/yourprintingsolution"
    };

    const handleSocialClick = (link) => {
        window.open(link, '_blank');
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth TransitionComponent={Fade}>
            <Box className="quote-modal-header">
                <Box className="quote-modal-title">
                    <FormatQuoteIcon className="quote-modal-title-icon" />
                    <Typography className="quote-modal-title-text">Get Quote</Typography>
                </Box>
                <IconButton onClick={onClose} className="quote-modal-close-btn">
                    <CloseIcon />
                </IconButton>
            </Box>
            
            <DialogContent className="quote-modal-content">
                <Fade in timeout={500}>
                    <Box>
                        <Typography className="quote-slogan">
                            "Your Printing Solution, Big or Small"
                        </Typography>
                        <Typography className="quote-subtitle">
                            Choose your preferred platform to get in touch with us
                        </Typography>
                    </Box>
                </Fade>

                <Grid container spacing={2} sx={{ mt: 2 }}>
                    <Grid item xs={6} sm={3}>
                        <Zoom in timeout={300}>
                            <Box className="social-icon-box" onClick={() => handleSocialClick(socialLinks.telegram)}>
                                <Box className="social-icon-circle social-telegram">
                                    <TelegramIcon className="social-icon" />
                                </Box>
                                <Typography className="social-label">Telegram</Typography>
                            </Box>
                        </Zoom>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                        <Zoom in timeout={400}>
                            <Box className="social-icon-box" onClick={() => handleSocialClick(socialLinks.facebook)}>
                                <Box className="social-icon-circle social-facebook">
                                    <FacebookIcon className="social-icon" />
                                </Box>
                                <Typography className="social-label">Facebook</Typography>
                            </Box>
                        </Zoom>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                        <Zoom in timeout={500}>
                            <Box className="social-icon-box" onClick={() => handleSocialClick(socialLinks.whatsapp)}>
                                <Box className="social-icon-circle social-whatsapp">
                                    <WhatsAppIcon className="social-icon" />
                                </Box>
                                <Typography className="social-label">WhatsApp</Typography>
                            </Box>
                        </Zoom>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                        <Zoom in timeout={600}>
                            <Box className="social-icon-box" onClick={() => handleSocialClick(socialLinks.instagram)}>
                                <Box className="social-icon-circle social-instagram">
                                    <InstagramIcon className="social-icon" />
                                </Box>
                                <Typography className="social-label">Instagram</Typography>
                            </Box>
                        </Zoom>
                    </Grid>
                </Grid>

                <Divider className="quote-divider" />
                <Typography variant="caption" className="quote-footer-text">
                    Click any platform to start a conversation with our team
                </Typography>
            </DialogContent>

            <DialogActions className="quote-modal-actions">
                <Button onClick={onClose} variant="outlined" className="btn-close-modal">
                    Close
                </Button>
            </DialogActions>
        </Dialog>
    );
};

// Feature Cards Component
const FeatureCards = () => {
    const features = [
        { icon: <SpeedIcon />, title: 'Fast Delivery', description: 'Within 24-48 hours' },
        { icon: <SecurityIcon />, title: 'Quality Guarantee', description: '100% satisfaction' },
        { icon: <SupportAgentIcon />, title: '24/7 Support', description: 'Customer first' },
        { icon: <LocalOfferIcon />, title: 'Best Prices', description: 'Competitive rates' }
    ];

    return (
        <Box className="features-section">
            <Container maxWidth="xl">
                <Grid container spacing={3}>
                    {features.map((feature, index) => (
                        <Grid item xs={12} sm={6} md={3} key={index}>
                            <Zoom in timeout={500 + index * 100}>
                                <Paper className="feature-card" elevation={0}>
                                    <Box className="feature-icon">{feature.icon}</Box>
                                    <Typography variant="h6" className="feature-title">
                                        {feature.title}
                                    </Typography>
                                    <Typography variant="body2" className="feature-description">
                                        {feature.description}
                                    </Typography>
                                </Paper>
                            </Zoom>
                        </Grid>
                    ))}
                </Grid>
            </Container>
        </Box>
    );
};

const DeviceList = ({ page }) => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const isTablet = useMediaQuery(theme.breakpoints.down('md'));
    const [devices, setDevices] = useState([]);
    const [categories, setCategories] = useState(FALLBACK_CATEGORIES);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredDevices, setFilteredDevices] = useState([]);
    const [categoryFilter, setCategoryFilter] = useState('');
    const [typeFilter, setTypeFilter] = useState('');
    const [sortBy, setSortBy] = useState('newest');
    const [viewMode, setViewMode] = useState('grid');
    const [showFilters, setShowFilters] = useState(!isMobile);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [quoteModalOpen, setQuoteModalOpen] = useState(false);
    const [showScrollTop, setShowScrollTop] = useState(false);
    const navigate = useNavigate();

    // Handle scroll to top button
    useEffect(() => {
        const handleScroll = () => {
            setShowScrollTop(window.scrollY > 500);
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const scrollToTop = () => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    // Load data
    useEffect(() => {
        const loadData = async () => {
            setLoading(true);
            setError(null);
            
            try {
                const devRes = page ? await getDevicesByPage(page) : await api.get('devices/');
                const deviceData = devRes.data || devRes;
                let devicesArray = Array.isArray(deviceData) ? deviceData : [];
                
                // Add mock ratings and review counts for demo
                devicesArray = devicesArray.map(device => ({
                    ...device,
                    rating: (Math.random() * 2 + 3).toFixed(1), // 3.0 - 5.0
                    reviewCount: Math.floor(Math.random() * 100) + 10,
                    isNew: Math.random() > 0.8
                }));
                
                setDevices(devicesArray);
                
                try {
                    const catRes = await api.get('categories/');
                    const categoryData = catRes.data || catRes;
                    if (Array.isArray(categoryData) && categoryData.length > 0) {
                        setCategories(categoryData);
                    }
                } catch (catErr) {
                    console.warn('Could not fetch categories, using fallback');
                }
            } catch (err) {
                console.error("Error loading devices:", err);
                setError("Failed to load products. Please try again later.");
                setDevices([]);
            } finally {
                setLoading(false);
            }
        };
        
        loadData();
    }, [page]);

    // Filter and sort devices
    useEffect(() => {
        let result = [...devices];
        
        // Search filter
        if (searchQuery) {
            result = result.filter(d => 
                d.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                d.description?.toLowerCase().includes(searchQuery.toLowerCase())
            );
        }
        
        // Category filter
        if (categoryFilter) {
            result = result.filter(d => String(d.category) === String(categoryFilter));
        }
        
        // Type filter
        if (typeFilter) {
            result = result.filter(d => d.type === typeFilter);
        }
        
        // Sorting
        result.sort((a, b) => {
            switch(sortBy) {
                case 'price_asc':
                    return parseFloat(a.price) - parseFloat(b.price);
                case 'price_desc':
                    return parseFloat(b.price) - parseFloat(a.price);
                case 'name_asc':
                    return a.name?.localeCompare(b.name);
                case 'newest':
                    return new Date(b.created_at) - new Date(a.created_at);
                default:
                    return 0;
            }
        });
        
        setFilteredDevices(result);
    }, [searchQuery, categoryFilter, typeFilter, devices, sortBy]);

    const getGridCols = () => {
        if (viewMode === 'list') return 1;
        if (isMobile) return 1;
        if (isTablet) return 2;
        return 3;
    };

    return (
        <Box className="device-list-wrapper">
            {/* Hero Section */}
            <Box className="hero-section">
                <Container maxWidth="xl">
                    <Fade in timeout={800}>
                        <Box className="hero-content">
                            <Typography variant="overline" className="hero-overline">
                                Welcome to Parrot Advert
                            </Typography>
                            <Typography variant="h1" className="hero-title">
                                Your Printing Solution
                            </Typography>
                            <Box className="slogan-container">
                                <Typography variant="h3" className="slogan-text">
                                    <span className="slogan-blue">Big</span>
                                    <span className="slogan-orange"> or </span>
                                    <span className="slogan-black">Small</span>
                                </Typography>
                            </Box>
                            <Typography variant="body1" className="hero-description">
                                Professional printing services tailored to your needs. 
                                Quality guaranteed, delivered with excellence.
                            </Typography>
                            <Button
                                variant="contained"
                                size="large"
                                startIcon={<FormatQuoteIcon />}
                                onClick={() => setQuoteModalOpen(true)}
                                className="hero-cta-button"
                            >
                                Get Quote Today
                            </Button>
                        </Box>
                    </Fade>
                </Container>
                <Box className="hero-bg-overlay" />
            </Box>

            {/* Features Section */}
            <FeatureCards />

            {/* Filter Section */}
            <Container maxWidth="xl" className="filter-section">
                <Paper elevation={0} className="filter-paper">
                    <Grid container spacing={2} alignItems="center">
                        <Grid item xs={12} md={5}>
                            <TextField 
                                fullWidth 
                                placeholder="Search products..." 
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="search-field"
                                InputProps={{
                                    startAdornment: (
                                        <InputAdornment position="start">
                                            <SearchIcon />
                                        </InputAdornment>
                                    ),
                                }}
                            />
                        </Grid>
                        
                        <Grid item xs={6} md={2}>
                            <FormControl fullWidth size="small">
                                <Select 
                                    value={sortBy} 
                                    onChange={(e) => setSortBy(e.target.value)}
                                    startAdornment={<SortIcon sx={{ mr: 1 }} />}
                                >
                                    {sortOptions.map(option => (
                                        <MenuItem key={option.value} value={option.value}>
                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                <span>{option.icon}</span>
                                                {option.label}
                                            </Box>
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                        </Grid>
                        
                        <Grid item xs={6} md={2}>
                            <Box className="view-toggle">
                                <IconButton 
                                    className={viewMode === 'grid' ? 'active' : ''}
                                    onClick={() => setViewMode('grid')}
                                >
                                    <ViewModuleIcon />
                                </IconButton>
                                <IconButton 
                                    className={viewMode === 'list' ? 'active' : ''}
                                    onClick={() => setViewMode('list')}
                                >
                                    <ViewListIcon />
                                </IconButton>
                            </Box>
                        </Grid>
                        
                        <Grid item xs={12} md={3}>
                            <Button 
                                fullWidth 
                                variant="outlined" 
                                className="filter-toggle-btn"
                                startIcon={<FilterListIcon />} 
                                onClick={() => setShowFilters(!showFilters)}
                            >
                                {showFilters ? 'Hide Filters' : 'Show Filters'}
                            </Button>
                        </Grid>
                    </Grid>

                    <Collapse in={showFilters}>
                        <Box className="filters-expanded">
                            <Grid container spacing={2}>
                                <Grid item xs={12} sm={6} md={4}>
                                    <FormControl fullWidth size="small">
                                        <InputLabel>Category</InputLabel>
                                        <Select 
                                            value={categoryFilter} 
                                            label="Category" 
                                            onChange={(e) => setCategoryFilter(e.target.value)}
                                        >
                                            <MenuItem value="">All Categories</MenuItem>
                                            {categories.map(c => (
                                                <MenuItem key={c.id} value={c.id}>
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                        <span>{c.icon || '📁'}</span>
                                                        {c.name}
                                                        <Chip label={c.count || 0} size="small" sx={{ ml: 1 }} />
                                                    </Box>
                                                </MenuItem>
                                            ))}
                                        </Select>
                                    </FormControl>
                                </Grid>

                                <Grid item xs={12} sm={6} md={4}>
                                    <FormControl fullWidth size="small">
                                        <InputLabel>Condition</InputLabel>
                                        <Select 
                                            value={typeFilter} 
                                            label="Condition" 
                                            onChange={(e) => setTypeFilter(e.target.value)}
                                        >
                                            <MenuItem value="">Any Condition</MenuItem>
                                            <MenuItem value="new">✨ Brand New</MenuItem>
                                            <MenuItem value="used">🔄 Used - Excellent</MenuItem>
                                            <MenuItem value="refurbished">🔧 Refurbished</MenuItem>
                                        </Select>
                                    </FormControl>
                                </Grid>

                                <Grid item xs={12} sm={6} md={4}>
                                    <Button 
                                        fullWidth 
                                        variant="contained" 
                                        color="error"
                                        onClick={() => {
                                            setSearchQuery('');
                                            setCategoryFilter('');
                                            setTypeFilter('');
                                            setSortBy('newest');
                                        }}
                                        className="reset-filters-btn"
                                    >
                                        Reset All Filters
                                    </Button>
                                </Grid>
                            </Grid>
                        </Box>
                    </Collapse>
                </Paper>
            </Container>

            {/* Results Stats */}
            <Container maxWidth="xl" className="results-stats">
                <Box className="stats-container">
                    <Typography variant="body2" className="stats-text">
                        Showing <strong>{filteredDevices.length}</strong> of <strong>{devices.length}</strong> products
                    </Typography>
                    {searchQuery && (
                        <Chip 
                            label={`Search: "${searchQuery}"`} 
                            size="small"
                            onDelete={() => setSearchQuery('')}
                            className="search-chip"
                        />
                    )}
                </Box>
            </Container>

            {/* Results Grid */}
            <Container maxWidth="xl" className="results-container">
                {loading ? (
                    <Grid container spacing={3}>
                        {Array(6).fill(0).map((_, i) => (
                            <Grid item xs={12} sm={6} md={4} lg={3} key={i}>
                                <Skeleton variant="rectangular" height={280} sx={{ borderRadius: 2 }} />
                                <Box sx={{ p: 2 }}>
                                    <Skeleton width="80%" />
                                    <Skeleton width="60%" />
                                    <Skeleton width="40%" />
                                </Box>
                            </Grid>
                        ))}
                    </Grid>
                ) : error ? (
                    <Box className="error-container">
                        <ErrorIcon className="error-icon" />
                        <Typography variant="h5" className="error-title">
                            Oops! Something went wrong
                        </Typography>
                        <Typography variant="body1" className="error-message">
                            {error}
                        </Typography>
                        <Button variant="contained" onClick={() => window.location.reload()}>
                            Try Again
                        </Button>
                    </Box>
                ) : filteredDevices.length > 0 ? (
                    <Grid container spacing={3}>
                        {filteredDevices.map((device, index) => (
                            <Grow in timeout={300 + index * 50} key={device.id}>
                                <Grid item xs={12} sm={6} md={4} lg={viewMode === 'list' ? 12 : 3}>
                                    <Card className={`device-card ${viewMode === 'list' ? 'list-view' : ''}`}>
                                        <Box className={`card-inner ${viewMode === 'list' ? 'list-layout' : ''}`}>
                                            <Box className="card-media">
                                                <DeviceImageSlider device={device} />
                                                {device.discount > 0 && (
                                                    <BlinkingDiscountBadge discount={device.discount} />
                                                )}
                                            </Box>
                                            
                                            <CardContent className="card-content">
                                                <Box className="card-header">
                                                    <Typography className="device-name" variant="h6">
                                                        {device.name}
                                                    </Typography>
                                                    <Box className="rating-container">
                                                        <Rating value={parseFloat(device.rating)} precision={0.5} size="small" readOnly />
                                                        <Typography variant="caption" className="review-count">
                                                            ({device.reviewCount})
                                                        </Typography>
                                                    </Box>
                                                </Box>
                                                
                                                <Typography className="device-description" variant="body2">
                                                    {device.description}
                                                </Typography>
                                                
                                                <Box className="card-footer">
                                                    <Box className="price-container">
                                                        {device.old_price && (
                                                            <Typography className="old-price">
                                                                ETB {parseFloat(device.old_price).toLocaleString()}
                                                            </Typography>
                                                        )}
                                                        <Typography className="price-tag">
                                                            ETB {parseFloat(device.price).toLocaleString()}
                                                        </Typography>
                                                    </Box>
                                                    
                                                    <Box className="action-buttons">
                                                        <Button 
                                                            className="view-btn"
                                                            size="small"
                                                            onClick={() => navigate(`/device/${device.id}`)}
                                                            startIcon={<VisibilityIcon />}
                                                        >
                                                            View Details
                                                        </Button>
                                                        <Button 
                                                            className="quote-btn"
                                                            size="small"
                                                            onClick={() => setQuoteModalOpen(true)}
                                                            startIcon={<FormatQuoteIcon />}
                                                        >
                                                            Get Quote
                                                        </Button>
                                                    </Box>
                                                </Box>
                                                
                                                {device.stock <= 5 && device.stock > 0 && (
                                                    <Chip 
                                                        label={`Only ${device.stock} left`} 
                                                        size="small" 
                                                        className="stock-warning"
                                                    />
                                                )}
                                            </CardContent>
                                        </Box>
                                    </Card>
                                </Grid>
                            </Grow>
                        ))}
                    </Grid>
                ) : (
                    <Box className="empty-state">
                        <Box className="empty-state-icon">🔍</Box>
                        <Typography variant="h5" className="empty-state-title">
                            No products found
                        </Typography>
                        <Typography variant="body1" className="empty-state-message">
                            Try adjusting your search or filter criteria
                        </Typography>
                        <Button variant="contained" onClick={() => {
                            setSearchQuery('');
                            setCategoryFilter('');
                            setTypeFilter('');
                        }}>
                            Clear all filters
                        </Button>
                    </Box>
                )}
            </Container>

            {/* Scroll to Top Button */}
            <Fade in={showScrollTop}>
                <IconButton className="scroll-to-top" onClick={scrollToTop}>
                    <KeyboardArrowUpIcon />
                </IconButton>
            </Fade>

            {/* Quote Modal */}
            <QuoteModal open={quoteModalOpen} onClose={() => setQuoteModalOpen(false)} />
        </Box>
    );
};

