import React, { useState, useEffect, useCallback, useMemo } from 'react';
import api from '../services/api';
import { Container, Row, Col, Card, Carousel, Button } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';
import { 
    TextField, InputAdornment, MenuItem, Select, FormControl, 
    InputLabel, Box, IconButton, Tooltip, Typography, Skeleton,
    Fade, Grow, Zoom, Paper, Chip, Rating, Badge, Drawer,
    useMediaQuery, useTheme, Slider, Switch, FormControlLabel
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import FilterListIcon from '@mui/icons-material/FilterList';
import ClearIcon from '@mui/icons-material/Clear';
import Inventory2Icon from '@mui/icons-material/Inventory2';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';
import VisibilityIcon from '@mui/icons-material/Visibility';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import LocalOfferIcon from '@mui/icons-material/LocalOffer';
import SpeedIcon from '@mui/icons-material/Speed';
import SecurityIcon from '@mui/icons-material/Security';
import SupportAgentIcon from '@mui/icons-material/SupportAgent';
import SortIcon from '@mui/icons-material/Sort';
import ViewModuleIcon from '@mui/icons-material/ViewModule';
import ViewListIcon from '@mui/icons-material/ViewList';
import CloseIcon from '@mui/icons-material/Close';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import { useNavigate } from 'react-router-dom';
import './Products.css';

// Feature Cards Component
const FeatureCards = () => {
    const features = [
        { icon: <SpeedIcon />, title: 'Fast Delivery', description: 'Within 24-48 hours', color: '#0046be' },
        { icon: <SecurityIcon />, title: 'Quality Guarantee', description: '100% satisfaction', color: '#ff8f00' },
        { icon: <SupportAgentIcon />, title: '24/7 Support', description: 'Customer first', color: '#0046be' },
        { icon: <LocalOfferIcon />, title: 'Best Prices', description: 'Competitive rates', color: '#ff8f00' }
    ];

    return (
        <Box className="features-section">
            <Container>
                <Row>
                    {features.map((feature, index) => (
                        <Col lg={3} md={6} xs={12} key={index} className="mb-4">
                            <Zoom in timeout={500 + index * 100}>
                                <Paper className="feature-card" elevation={0}>
                                    <Box className="feature-icon" style={{ backgroundColor: `${feature.color}15`, color: feature.color }}>
                                        {feature.icon}
                                    </Box>
                                    <Typography variant="h6" className="feature-title">
                                        {feature.title}
                                    </Typography>
                                    <Typography variant="body2" className="feature-description">
                                        {feature.description}
                                    </Typography>
                                </Paper>
                            </Zoom>
                        </Col>
                    ))}
                </Row>
            </Container>
        </Box>
    );
};

// Product Card Component
const ProductCard = ({ device, onViewDetails, onOrderNow }) => {
    const [isHovered, setIsHovered] = useState(false);
    const [currentImageIndex, setCurrentImageIndex] = useState(0);
    
    const images = [device.image1, device.image2, device.image3].filter(Boolean);
    
    useEffect(() => {
        if (!isHovered || images.length <= 1) return;
        const interval = setInterval(() => {
            setCurrentImageIndex((prev) => (prev + 1) % images.length);
        }, 3000);
        return () => clearInterval(interval);
    }, [isHovered, images.length]);

    const getStockStatus = (stock) => {
        if (stock > 20) return { text: 'In Stock', color: '#4caf50', icon: <CheckCircleIcon /> };
        if (stock > 0) return { text: 'Low Stock', color: '#ff9800', icon: null };
        return { text: 'Out of Stock', color: '#f44336', icon: null };
    };

    const stockStatus = getStockStatus(device.stock || 25);

    return (
        <Grow in timeout={300}>
            <Card 
                className="product-card"
                onMouseEnter={() => setIsHovered(true)}
                onMouseLeave={() => setIsHovered(false)}
            >
                <Box className="product-image-wrapper">
                    <div className="product-image-container">
                        <img 
                            src={images[currentImageIndex] || '/placeholder-image.jpg'} 
                            alt={device.name}
                            className="product-image"
                        />
                        {images.length > 1 && (
                            <Box className="image-nav-dots">
                                {images.map((_, idx) => (
                                    <span 
                                        key={idx}
                                        className={`dot ${currentImageIndex === idx ? 'active' : ''}`}
                                        onClick={() => setCurrentImageIndex(idx)}
                                    />
                                ))}
                            </Box>
                        )}
                    </div>
                    
                    {device.discount > 0 && (
                        <Badge 
                            badgeContent={`-${device.discount}%`} 
                            className="discount-badge"
                            sx={{ '& .MuiBadge-badge': { bgcolor: '#ff8f00', color: 'white', fontWeight: 'bold' } }}
                        />
                    )}
                    
                    {device.isNew && (
                        <Chip label="NEW" size="small" className="new-badge" />
                    )}
                    
                    <Fade in={isHovered}>
                        <Box className="product-overlay">
                            <Tooltip title="Quick View">
                                <IconButton className="overlay-btn" onClick={() => onViewDetails(device.id)}>
                                    <VisibilityIcon />
                                </IconButton>
                            </Tooltip>
                            <Tooltip title="Order Now">
                                <IconButton className="overlay-btn" onClick={() => onOrderNow(device.id)}>
                                    <ShoppingCartIcon />
                                </IconButton>
                            </Tooltip>
                        </Box>
                    </Fade>
                </Box>
                
                <Card.Body className="product-body">
                    <Box className="product-category">
                        <Chip 
                            label={device.category_name || 'Products'} 
                            size="small"
                            className="category-chip"
                        />
                        <Chip 
                            label={stockStatus.text}
                            size="small"
                            className="stock-chip"
                            style={{ backgroundColor: `${stockStatus.color}15`, color: stockStatus.color }}
                        />
                    </Box>
                    
                    <Typography className="product-title">
                        {device.name}
                    </Typography>
                    
                    <Box className="rating-container">
                        <Rating value={device.rating || 4.5} precision={0.5} size="small" readOnly />
                        <Typography variant="caption" className="review-count">
                            ({device.reviewCount || Math.floor(Math.random() * 100) + 10} reviews)
                        </Typography>
                    </Box>
                    
                    <Typography className="product-description">
                        {device.description?.substring(0, 80)}...
                    </Typography>
                    
                    <Box className="price-container">
                        {device.old_price && (
                            <Typography className="old-price">
                                ETB {parseFloat(device.old_price).toLocaleString()}
                            </Typography>
                        )}
                        <Typography className="current-price">
                            ETB {parseFloat(device.price).toLocaleString()}
                        </Typography>
                    </Box>
                    
                    <Box className="product-actions">
                        <Button 
                            variant="outlined"
                            className="details-btn"
                            onClick={() => onViewDetails(device.id)}
                            startIcon={<VisibilityIcon />}
                        >
                            Details
                        </Button>
                        <Button 
                            variant="contained"
                            className="order-btn"
                            onClick={() => onOrderNow(device.id)}
                            startIcon={<ShoppingCartIcon />}
                        >
                            Order
                        </Button>
                    </Box>
                </Card.Body>
            </Card>
        </Grow>
    );
};

const Products = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const isTablet = useMediaQuery(theme.breakpoints.down('md'));
    const [devices, setDevices] = useState([]);
    const [categories, setCategories] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredDevices, setFilteredDevices] = useState([]);
    const [priceRange, setPriceRange] = useState([0, 50000]);
    const [categoryFilter, setCategoryFilter] = useState('');
    const [sortBy, setSortBy] = useState('newest');
    const [showFilters, setShowFilters] = useState(!isMobile);
    const [loading, setLoading] = useState(true);
    const [viewMode, setViewMode] = useState('grid');
    const [showMobileFilters, setShowMobileFilters] = useState(false);
    const [showScrollTop, setShowScrollTop] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const handleScroll = () => {
            setShowScrollTop(window.scrollY > 500);
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const scrollToTop = () => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    useEffect(() => {
        fetchProducts();
        fetchCategories();
    }, []);

    useEffect(() => {
        filterAndSortDevices();
    }, [searchQuery, priceRange, categoryFilter, sortBy, devices]);

    const fetchProducts = () => {
        setLoading(true);
        api.get('devices/?page=Product')
            .then(response => {
                let products = response.data;
                // Add mock data for demo
                products = products.map(product => ({
                    ...product,
                    rating: (Math.random() * 2 + 3).toFixed(1),
                    reviewCount: Math.floor(Math.random() * 100) + 10,
                    isNew: Math.random() > 0.8,
                    stock: Math.floor(Math.random() * 50) + 5
                }));
                setDevices(products);
                setLoading(false);
            })
            .catch(error => {
                console.error('Error fetching products:', error);
                api.get('devices/')
                    .then(response => {
                        let products = response.data.filter(d => d.page === 'Product');
                        products = products.map(product => ({
                            ...product,
                            rating: (Math.random() * 2 + 3).toFixed(1),
                            reviewCount: Math.floor(Math.random() * 100) + 10,
                            isNew: Math.random() > 0.8,
                            stock: Math.floor(Math.random() * 50) + 5
                        }));
                        setDevices(products);
                        setLoading(false);
                    });
            });
    };

    const fetchCategories = () => {
        api.get('categories/')
            .then(response => setCategories(response.data))
            .catch(error => console.error('Error fetching categories:', error));
    };

    const filterAndSortDevices = () => {
        let filtered = devices.filter(device => device.page === 'Product');

        if (searchQuery) {
            filtered = filtered.filter(device =>
                device.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                device.description.toLowerCase().includes(searchQuery.toLowerCase())
            );
        }

        if (priceRange[1] < 50000) {
            filtered = filtered.filter(device => device.price >= priceRange[0] && device.price <= priceRange[1]);
        }

        if (categoryFilter) {
            filtered = filtered.filter(device => device.category === parseInt(categoryFilter));
        }

        switch (sortBy) {
            case 'price-low':
                filtered.sort((a, b) => a.price - b.price);
                break;
            case 'price-high':
                filtered.sort((a, b) => b.price - a.price);
                break;
            case 'rating':
                filtered.sort((a, b) => (b.rating || 0) - (a.rating || 0));
                break;
            case 'name':
                filtered.sort((a, b) => a.name.localeCompare(b.name));
                break;
            default:
                filtered.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
        }

        setFilteredDevices(filtered);
    };

    const handleViewDetails = (id) => {
        navigate(`/device/${id}`);
    };

    const handleOrderNow = (id) => {
        navigate(`/order/${id}`);
    };

    const renderSkeletons = () => Array(8).fill(0).map((_, index) => (
        <Col lg={3} md={6} xs={12} key={index} className="mb-4">
            <Card className="product-card-skeleton">
                <Skeleton variant="rectangular" height={250} animation="wave" />
                <Card.Body>
                    <Skeleton variant="text" width="60%" height={30} />
                    <Skeleton variant="text" width="40%" />
                    <Skeleton variant="text" width="80%" />
                    <Box sx={{ mt: 2 }}>
                        <Skeleton variant="rectangular" height={40} />
                    </Box>
                </Card.Body>
            </Card>
        </Col>
    ));

    const FilterContent = () => (
        <Box className="filter-content">
            <Box className="filter-header">
                <Typography variant="h6" className="filter-title">Filters</Typography>
                {isMobile && (
                    <IconButton onClick={() => setShowMobileFilters(false)}>
                        <CloseIcon />
                    </IconButton>
                )}
            </Box>
            
            <Box className="filter-group">
                <Typography variant="subtitle2" className="filter-label">Categories</Typography>
                <FormControl fullWidth size="small">
                    <Select 
                        value={categoryFilter} 
                        onChange={(e) => setCategoryFilter(e.target.value)}
                        className="filter-select"
                    >
                        <MenuItem value="">All Categories</MenuItem>
                        {categories.map(c => (
                            <MenuItem key={c.id} value={c.id}>
                                {c.name}
                            </MenuItem>
                        ))}
                    </Select>
                </FormControl>
            </Box>
            
            <Box className="filter-group">
                <Typography variant="subtitle2" className="filter-label">Price Range</Typography>
                <Slider
                    value={priceRange}
                    onChange={(e, newValue) => setPriceRange(newValue)}
                    valueLabelDisplay="auto"
                    min={0}
                    max={50000}
                    className="price-slider"
                />
                <Box className="price-range-values">
                    <Typography variant="caption">ETB {priceRange[0].toLocaleString()}</Typography>
                    <Typography variant="caption">ETB {priceRange[1].toLocaleString()}</Typography>
                </Box>
            </Box>
            
            <Box className="filter-group">
                <Typography variant="subtitle2" className="filter-label">Sort By</Typography>
                <FormControl fullWidth size="small">
                    <Select 
                        value={sortBy} 
                        onChange={(e) => setSortBy(e.target.value)}
                        className="filter-select"
                    >
                        <MenuItem value="newest">Newest First</MenuItem>
                        <MenuItem value="price-low">Price: Low to High</MenuItem>
                        <MenuItem value="price-high">Price: High to Low</MenuItem>
                        <MenuItem value="rating">Top Rated</MenuItem>
                        <MenuItem value="name">Name: A to Z</MenuItem>
                    </Select>
                </FormControl>
            </Box>
            
            <Button 
                variant="outlined" 
                fullWidth
                onClick={() => {
                    setSearchQuery('');
                    setCategoryFilter('');
                    setPriceRange([0, 50000]);
                    setSortBy('newest');
                }}
                className="reset-filters-btn"
            >
                Reset All Filters
            </Button>
        </Box>
    );

    const getGridCols = () => {
        if (viewMode === 'list') return 1;
        if (isMobile) return 1;
        if (isTablet) return 2;
        return 3;
    };

    return (
        <Box className="products-page">
            {/* Hero Section */}
            <Box className="products-hero">
                <Container>
                    <Fade in timeout={800}>
                        <Box className="hero-content">
                            <Typography variant="overline" className="hero-overline">
                                Premium Quality
                            </Typography>
                            <Typography variant="h1" className="hero-title">
                                Our Products
                            </Typography>
                            <Typography variant="h5" className="hero-subtitle">
                                Discover our premium printing solutions and materials
                            </Typography>
                            <Typography variant="body1" className="hero-description">
                                High-quality products designed to meet your professional printing needs
                            </Typography>
                        </Box>
                    </Fade>
                </Container>
                <Box className="hero-bg-overlay" />
            </Box>

            {/* Features Section */}
            <FeatureCards />

            {/* Main Content */}
            <Container className="products-main">
                {/* Search and Filter Bar */}
                <Paper className="search-filter-bar" elevation={0}>
                    <Row className="align-items-center">
                        <Col md={5} lg={6}>
                            <TextField
                                variant="outlined"
                                placeholder="Search products..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                fullWidth
                                className="search-input"
                                InputProps={{
                                    startAdornment: <InputAdornment position="start"><SearchIcon /></InputAdornment>,
                                    endAdornment: searchQuery && (
                                        <InputAdornment position="end">
                                            <IconButton onClick={() => setSearchQuery('')} size="small">
                                                <ClearIcon />
                                            </IconButton>
                                        </InputAdornment>
                                    )
                                }}
                            />
                        </Col>
                        
                        <Col md={3} lg={3}>
                            <FormControl fullWidth size="small" className="sort-select">
                                <InputLabel>Sort By</InputLabel>
                                <Select 
                                    value={sortBy} 
                                    onChange={(e) => setSortBy(e.target.value)}
                                    label="Sort By"
                                    startAdornment={<SortIcon sx={{ mr: 1 }} />}
                                >
                                    <MenuItem value="newest">Newest First</MenuItem>
                                    <MenuItem value="price-low">Price: Low to High</MenuItem>
                                    <MenuItem value="price-high">Price: High to Low</MenuItem>
                                    <MenuItem value="rating">Top Rated</MenuItem>
                                    <MenuItem value="name">Name: A to Z</MenuItem>
                                </Select>
                            </FormControl>
                        </Col>
                        
                        <Col md={2} lg={2}>
                            <Box className="view-toggle">
                                <Tooltip title="Grid View">
                                    <IconButton 
                                        className={viewMode === 'grid' ? 'active' : ''}
                                        onClick={() => setViewMode('grid')}
                                    >
                                        <ViewModuleIcon />
                                    </IconButton>
                                </Tooltip>
                                <Tooltip title="List View">
                                    <IconButton 
                                        className={viewMode === 'list' ? 'active' : ''}
                                        onClick={() => setViewMode('list')}
                                    >
                                        <ViewListIcon />
                                    </IconButton>
                                </Tooltip>
                            </Box>
                        </Col>
                        
                        <Col md={2} lg={1}>
                            {isMobile ? (
                                <Button 
                                    variant="outlined" 
                                    fullWidth
                                    onClick={() => setShowMobileFilters(true)}
                                    startIcon={<FilterListIcon />}
                                    className="filter-btn-mobile"
                                >
                                    Filter
                                </Button>
                            ) : (
                                <Button 
                                    variant="outlined" 
                                    fullWidth
                                    onClick={() => setShowFilters(!showFilters)}
                                    startIcon={<FilterListIcon />}
                                    className="filter-btn"
                                >
                                    {showFilters ? 'Hide' : 'Filters'}
                                </Button>
                            )}
                        </Col>
                    </Row>
                </Paper>

                {/* Desktop Filters */}
                {!isMobile && showFilters && (
                    <Paper className="filters-panel" elevation={0}>
                        <FilterContent />
                    </Paper>
                )}

                {/* Mobile Filters Drawer */}
                <Drawer
                    anchor="right"
                    open={showMobileFilters}
                    onClose={() => setShowMobileFilters(false)}
                    className="mobile-filters-drawer"
                >
                    <FilterContent />
                </Drawer>

                {/* Results Stats */}
                <Box className="results-stats">
                    <Typography variant="body2" className="stats-text">
                        Showing <strong>{filteredDevices.length}</strong> of <strong>{devices.length}</strong> products
                    </Typography>
                    {searchQuery && (
                        <Chip 
                            label={`Search: "${searchQuery}"`} 
                            size="small"
                            onDelete={() => setSearchQuery('')}
                            className="search-chip"
                        />
                    )}
                </Box>

                {/* Products Grid */}
                <Row className={`products-grid ${viewMode === 'list' ? 'list-view' : ''}`}>
                    {loading ? (
                        renderSkeletons()
                    ) : filteredDevices.length > 0 ? (
                        filteredDevices.map(device => (
                            <Col lg={getGridCols()} md={6} sm={12} xs={12} key={device.id} className="mb-4">
                                <ProductCard 
                                    device={device}
                                    onViewDetails={handleViewDetails}
                                    onOrderNow={handleOrderNow}
                                />
                            </Col>
                        ))
                    ) : (
                        <Box className="empty-state">
                            <Inventory2Icon className="empty-icon" />
                            <Typography variant="h5" className="empty-title">
                                No products found
                            </Typography>
                            <Typography variant="body1" className="empty-message">
                                Try adjusting your search or filter criteria
                            </Typography>
                            <Button 
                                variant="contained" 
                                onClick={() => {
                                    setSearchQuery('');
                                    setCategoryFilter('');
                                    setPriceRange([0, 50000]);
                                    setSortBy('newest');
                                }}
                                className="empty-reset-btn"
                            >
                                Clear all filters
                            </Button>
                        </Box>
                    )}
                </Row>
            </Container>

            {/* Scroll to Top Button */}
            <Fade in={showScrollTop}>
                <IconButton className="scroll-to-top" onClick={scrollToTop}>
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M12 4L12 20M12 4L18 10M12 4L6 10" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                </IconButton>
            </Fade>
        </Box>
    );
};

export default Products;