import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  Typography,
  Tabs,
  Tab,
  ImageList,
  ImageListItem,
  Card,
  CardMedia,
  Chip,
  Dialog,
  DialogContent,
  Button,
  IconButton,
  Fade,
  Grow,
  Skeleton,
  Rating,
  useMediaQuery,
  useTheme,
  Alert,
  AlertTitle
} from '@mui/material';
import ZoomInIcon from '@mui/icons-material/ZoomIn';
import CloseIcon from '@mui/icons-material/Close';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';
import VisibilityIcon from '@mui/icons-material/Visibility';
import ErrorIcon from '@mui/icons-material/Error';
import api from '../services/api';
import './Portfolio.css';

const Portfolio = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const isTablet = useMediaQuery(theme.breakpoints.down('lg'));
  const [tabValue, setTabValue] = useState(0);
  const [openDialog, setOpenDialog] = useState(false);
  const [selectedDevice, setSelectedDevice] = useState(null);
  const [devices, setDevices] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch real device data and categories from API
  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      setError(null);
      
      try {
        // Fetch categories first
        let categoriesData = [];
        let categoriesMap = {};
        
        try {
          const catRes = await api.get('categories/');
          categoriesData = catRes.data || catRes;
          if (Array.isArray(categoriesData)) {
            // Create a map of category id -> category name
            categoriesData.forEach(cat => {
              categoriesMap[cat.id] = cat.name;
            });
            // Set categories list for tabs (add 'All' at the beginning)
            const categoryNames = ['All', ...categoriesData.map(cat => cat.name)];
            setCategories(categoryNames);
          }
        } catch (catErr) {
          console.warn('Could not fetch categories:', catErr);
        }

        // Fetch devices
        const response = await api.get('devices/');
        let devicesData = response.data || response;
        let devicesArray = Array.isArray(devicesData) ? devicesData : [];
        
        // Process devices to include category name and other fields
        devicesArray = devicesArray.map(device => {
          // Get category name from the map using category id
          let categoryName = 'Uncategorized';
          
          // Handle different possible structures from API
          if (device.category) {
            // If category is an object (expanded relationship)
            if (typeof device.category === 'object' && device.category.name) {
              categoryName = device.category.name;
            } 
            // If category is a number (ID)
            else if (typeof device.category === 'number' && categoriesMap[device.category]) {
              categoryName = categoriesMap[device.category];
            }
            // If category is a string
            else if (typeof device.category === 'string') {
              categoryName = device.category;
            }
          }
          
          // Also check for category_id field
          if (device.category_id && categoriesMap[device.category_id]) {
            categoryName = categoriesMap[device.category_id];
          }
          
          // Check if category is nested in category object
          if (device.category_obj && device.category_obj.name) {
            categoryName = device.category_obj.name;
          }
          
          return {
            ...device,
            category: categoryName,
            category_id: device.category_id || (device.category?.id || device.category),
            rating: device.rating || (Math.random() * 2 + 3).toFixed(1),
            reviewCount: device.reviewCount || Math.floor(Math.random() * 100) + 10,
            img: device.image1 || device.image2 || device.image3 || '/placeholder-electronics.png'
          };
        });
        
        setDevices(devicesArray);
        
        // If categories weren't fetched from API, extract from devices
        if (categoriesData.length === 0) {
          const uniqueCategories = ['All', ...new Set(devicesArray.map(device => device.category))];
          setCategories(uniqueCategories);
        }
        
      } catch (err) {
        console.error("Error loading devices:", err);
        setError("Failed to load portfolio items. Please try again later.");
        setDevices([]);
      } finally {
        setLoading(false);
      }
    };
    
    loadData();
  }, []);

  // Filter devices based on selected tab using category name
  const filteredDevices = tabValue === 0 
    ? devices 
    : devices.filter(device => device.category === categories[tabValue]);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleDeviceClick = (device) => {
    setSelectedDevice(device);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setSelectedDevice(null);
  };

  const getGridCols = () => {
    if (isMobile) return 1;
    if (isTablet) return 2;
    return 3;
  };

  // Get category icon or emoji based on category name
  const getCategoryIcon = (category) => {
    const icons = {
      'Printers': '🖨️',
      'Scanners': '📠',
      'Copiers': '📄',
      'Copier': '📄',
      'Accessories': '🔌',
      'Supplies': '📦',
      'T-Shirts': '👕',
      'Banners': '🎏',
      'Posters/Stickers': '📯',
      'Design Projects': '🎨',
      'Others': '📁',
      'Uncategorized': '📁'
    };
    return icons[category] || '📁';
  };

  // Loading skeleton
  const LoadingSkeleton = () => (
    <ImageList variant="masonry" cols={getGridCols()} gap={24} className="portfolio-grid">
      {Array(6).fill(0).map((_, index) => (
        <ImageListItem key={index}>
          <Card className="portfolio-card">
            <Skeleton variant="rectangular" height={300} />
            <Box className="card-content" sx={{ p: 2 }}>
              <Skeleton width="80%" height={32} />
              <Skeleton width="60%" height={24} sx={{ mt: 1 }} />
              <Skeleton width="90%" height={40} sx={{ mt: 1 }} />
            </Box>
          </Card>
        </ImageListItem>
      ))}
    </ImageList>
  );

  // Error display
  if (error) {
    return (
      <Box className="portfolio-container">
        <Container maxWidth="lg" sx={{ py: 8 }}>
          <Alert severity="error" icon={<ErrorIcon />}>
            <AlertTitle>Error Loading Portfolio</AlertTitle>
            {error}
            <Button 
              variant="contained" 
              onClick={() => window.location.reload()} 
              sx={{ mt: 2 }}
            >
              Try Again
            </Button>
          </Alert>
        </Container>
      </Box>
    );
  }

  return (
    <Box className="portfolio-container">
      {/* Hero Section */}
      <Box className="portfolio-hero">
        <Container maxWidth="lg">
          <Fade in timeout={800}>
            <Box className="hero-content">
              <Typography variant="overline" className="hero-overline">
                Our Creative Showcase
              </Typography>
              <Typography variant="h1" className="hero-title">
                Portfolio
              </Typography>
              <Typography variant="h5" className="hero-subtitle">
                Discover Parrot Advert's creative work across Printers, Scanners, Copiers, and more.
                Professional quality products that meet your printing needs.
              </Typography>
              <Button
                variant="contained"
                href="https://www.youtube.com/watch?v=0pKxVkWeWCA"
                target="_blank"
                rel="noopener noreferrer"
                className="hero-button"
                startIcon={<PlayArrowIcon />}
              >
                Watch Our Work Video Preview
              </Button>
            </Box>
          </Fade>
        </Container>
        <Box className="hero-bg-overlay" />
      </Box>

      {/* Category Tabs - Using category names */}
      <Container maxWidth="xl" className="portfolio-content">
        <Box className="tabs-container">
          <Tabs 
            value={tabValue} 
            onChange={handleTabChange}
            variant="scrollable"
            scrollButtons="auto"
            className="portfolio-tabs"
          >
            {categories.map((category, index) => {
              const categoryCount = index === 0 
                ? devices.length 
                : devices.filter(d => d.category === category).length;
              
              return (
                <Tab 
                  key={category} 
                  label={
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <span>{getCategoryIcon(category)}</span>
                      <span>
                        {category}
                        {category !== 'All' && (
                          <Typography component="span" sx={{ ml: 1, fontSize: '0.75rem', opacity: 0.8 }}>
                            ({categoryCount})
                          </Typography>
                        )}
                        {category === 'All' && (
                          <Typography component="span" sx={{ ml: 1, fontSize: '0.75rem', opacity: 0.8 }}>
                            ({categoryCount})
                          </Typography>
                        )}
                      </span>
                    </Box>
                  }
                  className="portfolio-tab"
                />
              );
            })}
          </Tabs>
        </Box>

        {/* Debug Info - Remove in production */}
        {/* {process.env.NODE_ENV === 'development' && devices.length > 0 && (
          <Box sx={{ mb: 2, p: 2, bgcolor: '#f0f0f0', borderRadius: 2 }}>
            <Typography variant="caption" component="div">
              Debug: First device category: {devices[0]?.category} (ID: {devices[0]?.category_id})
            </Typography>
            <Typography variant="caption" component="div">
              Available categories: {categories.join(', ')}
            </Typography>
          </Box>
        )} */}

        {/* Portfolio Grid */}
        {loading ? (
          <LoadingSkeleton />
        ) : filteredDevices.length > 0 ? (
          <ImageList
            variant="masonry"
            cols={getGridCols()}
            gap={24}
            className="portfolio-grid"
          >
            {filteredDevices.map((device, index) => (
              <Grow in timeout={500 + (index * 50)} key={device.id}>
                <ImageListItem className="portfolio-item">
                  <Card 
                    className="portfolio-card"
                    onClick={() => handleDeviceClick(device)}
                  >
                    <Box className="card-image-wrapper">
                      <CardMedia
                        component="img"
                        image={device.img}
                        alt={device.name}
                        className="card-image"
                        onError={(e) => {
                          e.target.src = '/placeholder-electronics.png';
                        }}
                      />
                      <Box className="card-overlay">
                        <IconButton className="zoom-icon">
                          <ZoomInIcon />
                        </IconButton>
                      </Box>
                      {device.discount > 0 && (
                        <Chip 
                          label={`-${device.discount}%`} 
                          size="small"
                          color="error"
                          className="discount-badge"
                        />
                      )}
                      {device.isNew && (
                        <Chip 
                          label="NEW" 
                          size="small"
                          color="success"
                          className="new-badge"
                        />
                      )}
                    </Box>
                    <Box className="card-content">
                      <Typography variant="h6" className="card-title">
                        {device.name}
                      </Typography>
                      <Box className="rating-container">
                        <Rating 
                          value={parseFloat(device.rating)} 
                          precision={0.5} 
                          size="small" 
                          readOnly 
                        />
                        <Typography variant="caption" className="review-count">
                          ({device.reviewCount})
                        </Typography>
                      </Box>
                      <Chip 
                        label={device.category} 
                        size="small"
                        className="card-category"
                        icon={<span>{getCategoryIcon(device.category)}</span>}
                      />
                      <Typography variant="body2" className="card-description">
                        {device.description?.substring(0, 80)}...
                      </Typography>
                      <Box className="price-container">
                        {device.old_price && (
                          <Typography className="old-price">
                            ETB {parseFloat(device.old_price).toLocaleString()}
                          </Typography>
                        )}
                        <Typography className="price-tag">
                          ETB {parseFloat(device.price).toLocaleString()}
                        </Typography>
                      </Box>
                      {device.stock <= 5 && device.stock > 0 && (
                        <Chip 
                          label={`Only ${device.stock} left in stock`} 
                          size="small"
                          className="stock-warning"
                        />
                      )}
                    </Box>
                  </Card>
                </ImageListItem>
              </Grow>
            ))}
          </ImageList>
        ) : (
          <Box className="no-results">
            <Typography variant="h6">No products found in {categories[tabValue]} category.</Typography>
            <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
              Check back later for new products in this category.
            </Typography>
          </Box>
        )}
      </Container>

      {/* Lightbox Dialog */}
      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="lg"
        fullWidth
        className="portfolio-dialog"
        TransitionComponent={Fade}
        transitionDuration={400}
      >
        {selectedDevice && (
          <DialogContent className="dialog-content">
            <IconButton className="dialog-close-btn" onClick={handleCloseDialog}>
              <CloseIcon />
            </IconButton>
            <Box className="dialog-image-container">
              <img
                src={selectedDevice.img}
                alt={selectedDevice.name}
                className="dialog-image"
                onError={(e) => {
                  e.target.src = '/placeholder-electronics.png';
                }}
              />
              <Box className="dialog-info">
                <Typography variant="h4" className="dialog-title">
                  {selectedDevice.name}
                </Typography>
                <Box className="dialog-rating">
                  <Rating 
                    value={parseFloat(selectedDevice.rating)} 
                    precision={0.5} 
                    readOnly 
                    size="large"
                  />
                  <Typography variant="body2">
                    ({selectedDevice.reviewCount} reviews)
                  </Typography>
                </Box>
                <Chip 
                  label={selectedDevice.category} 
                  className="dialog-category"
                  icon={<span>{getCategoryIcon(selectedDevice.category)}</span>}
                  sx={{ alignSelf: 'flex-start', mb: 2 }}
                />
                <Typography variant="body1" className="dialog-description">
                  {selectedDevice.description}
                </Typography>
                <Box className="dialog-price">
                  {selectedDevice.old_price && (
                    <Typography className="dialog-old-price">
                      ETB {parseFloat(selectedDevice.old_price).toLocaleString()}
                    </Typography>
                  )}
                  <Typography className="dialog-current-price">
                    ETB {parseFloat(selectedDevice.price).toLocaleString()}
                  </Typography>
                </Box>
                <Box className="dialog-tags">
                  {selectedDevice.type && (
                    <Chip 
                      label={`Condition: ${selectedDevice.type === 'new' ? 'Brand New' : selectedDevice.type === 'used' ? 'Used - Excellent' : 'Refurbished'}`} 
                      className="dialog-tag"
                    />
                  )}
                  {selectedDevice.price_type && (
                    <Chip 
                      label={`Price: ${selectedDevice.price_type === 'fixed' ? 'Fixed Price' : 'Negotiable'}`} 
                      className="dialog-tag"
                    />
                  )}
                  {selectedDevice.stock > 0 ? (
                    <Chip 
                      label={`In Stock: ${selectedDevice.stock} units`} 
                      className="dialog-tag"
                      sx={{ backgroundColor: 'rgba(76, 175, 80, 0.2)', color: '#4caf50' }}
                    />
                  ) : (
                    <Chip 
                      label="Out of Stock" 
                      className="dialog-tag"
                      sx={{ backgroundColor: 'rgba(244, 67, 54, 0.2)', color: '#f44336' }}
                    />
                  )}
                </Box>
                <Box className="dialog-actions">
                  <Button
                    variant="contained"
                    startIcon={<ShoppingCartIcon />}
                    className="dialog-cart-btn"
                    disabled={selectedDevice.stock === 0}
                  >
                    {selectedDevice.stock > 0 ? 'Add to Cart' : 'Out of Stock'}
                  </Button>
                  <Button
                    variant="outlined"
                    startIcon={<VisibilityIcon />}
                    className="dialog-view-btn"
                    onClick={() => {
                      handleCloseDialog();
                      window.location.href = `/device/${selectedDevice.id}`;
                    }}
                  >
                    View Full Details
                  </Button>
                </Box>
              </Box>
            </Box>
          </DialogContent>
        )}
      </Dialog>
    </Box>
  );
};

export default Portfolio;