import React, { useState } from 'react';
import { 
    Container, TextField, Button, Typography, Box, Paper, 
    Alert, AlertTitle, Grid, IconButton, Stack, CircularProgress 
} from '@mui/material';
import axios from 'axios';
import { 
    Facebook, Telegram, WhatsApp, Instagram, 
    Email, LocationOn, Phone, Send 
} from '@mui/icons-material';

const ContactUs = () => {
    const [formData, setFormData] = useState({ name: '', email: '', message: '' });
    const [loading, setLoading] = useState(false);
    const [status, setStatus] = useState({ type: '', msg: '' });

    const getCsrfToken = (name) => {
        let cookieValue = null;
        if (document.cookie && document.cookie !== '') {
            const cookies = document.cookie.split(';');
            for (let i = 0; i < cookies.length; i++) {
                const cookie = cookies[i].trim();
                if (cookie.substring(0, name.length + 1) === (name + '=')) {
                    cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
                    break;
                }
            }
        }
        return cookieValue;
    };

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (event) => {
        event.preventDefault();
        setLoading(true);
        try {
            // Replace with your actual endpoint
            const csrfToken = getCsrfToken('csrftoken');
            if (!csrfToken) {
                throw new Error('CSRF token not found. Please refresh the page.');
            }
            await axios.post('/api/contact/', formData, {
                headers: {
                    'X-CSRFToken': csrfToken,
                    'Content-Type': 'application/json',
                },
                withCredentials: true,
            });
            setStatus({ type: 'success', msg: 'Your message has been sent successfully!' });
            setFormData({ name: '', email: '', message: '' });
        } catch (error) {
            setStatus({ type: 'error', msg: 'Failed to send message. Please try again later.' });
        } finally {
            setLoading(false);
        }
    };

    const socialLinks = [
        { icon: <Facebook />, color: '#1877F2', url: 'https://www.facebook.com/100063858214255' },
        { icon: <Telegram />, color: '#0088cc', url: 'https://t.me/joinchat/SHD4s9qik_hu-pl8' },
        { icon: <WhatsApp />, color: '#25D366', url: 'https://wa.me/YOUR_PHONE_NUMBER' },
        { icon: <Instagram />, color: '#E4405F', url: 'https://www.instagram.com/YOUR_USERNAME' },
    ];

    return (
        <Container maxWidth="lg" sx={{ py: { xs: 4, md: 8 } }}>
            <Paper elevation={20} sx={{ borderRadius: 4, overflow: 'hidden' }}>
                <Grid container>
                    {/* Left Panel: Brand & Info */}
                    <Grid item xs={12} md={5} sx={{ 
                        background: 'linear-gradient(135deg, #1A237E 0%, #0D47A1 100%)', // Professional Deep Blue
                        color: 'white',
                        p: { xs: 4, md: 6 },
                        display: 'flex',
                        flexDirection: 'column',
                        justifyContent: 'space-between'
                    }}>
                        <Box>
                            <Typography variant="h3" fontWeight={800} gutterBottom sx={{ color: '#FFD700' }}>
                                Get in Touch
                            </Typography>
                            <Typography variant="body1" sx={{ opacity: 0.85, mb: 4, fontSize: '1.1rem' }}>
                                Have questions? We're here to help. Reach out to us through any of these channels.
                            </Typography>

                            <Stack spacing={4} sx={{ mb: 6 }}>
                                <Box display="flex" alignItems="center" gap={3}>
                                    <Box sx={{ p: 1, bgcolor: 'rgba(255,215,0,0.1)', borderRadius: 2, color: '#FFD700' }}>
                                        <Phone />
                                    </Box>
                                    <Typography variant="body1">+251 900 000 000</Typography>
                                </Box>
                                <Box display="flex" alignItems="center" gap={3}>
                                    <Box sx={{ p: 1, bgcolor: 'rgba(255,215,0,0.1)', borderRadius: 2, color: '#FFD700' }}>
                                        <Email />
                                    </Box>
                                    <Typography variant="body1">info@yourcompany.com</Typography>
                                </Box>
                                <Box display="flex" alignItems="center" gap={3}>
                                    <Box sx={{ p: 1, bgcolor: 'rgba(255,215,0,0.1)', borderRadius: 2, color: '#FFD700' }}>
                                        <LocationOn />
                                    </Box>
                                    <Typography variant="body1">Addis Ababa, Ethiopia</Typography>
                                </Box>
                            </Stack>
                        </Box>

                        <Box>
                            <Typography variant="h6" sx={{ mb: 2, fontWeight: 600 }}>Social Media</Typography>
                            <Stack direction="row" spacing={2}>
                                {socialLinks.map((social, index) => (
                                    <IconButton 
                                        key={index}
                                        component="a"
                                        href={social.url}
                                        target="_blank"
                                        sx={{ 
                                            color: 'white', 
                                            bgcolor: 'rgba(255,255,255,0.1)',
                                            transition: 'all 0.3s ease',
                                            '&:hover': { 
                                                bgcolor: social.color, 
                                                transform: 'translateY(-5px)',
                                                boxShadow: `0 4px 12px ${social.color}66`
                                            }
                                        }}
                                    >
                                        {social.icon}
                                    </IconButton>
                                ))}
                            </Stack>
                        </Box>
                    </Grid>

                    {/* Right Panel: The Form */}
                    <Grid item xs={12} md={7} sx={{ p: { xs: 4, md: 6 }, bgcolor: '#FFFFFF' }}>
                        {status.msg && (
                            <Alert 
                                severity={status.type} 
                                sx={{ mb: 4, borderRadius: 2 }} 
                                onClose={() => setStatus({ type: '', msg: '' })}
                            >
                                <AlertTitle sx={{ fontWeight: 700 }}>
                                    {status.type === 'success' ? 'Sent!' : 'Error'}
                                </AlertTitle>
                                {status.msg}
                            </Alert>
                        )}

                        <form onSubmit={handleSubmit}>
                            <Typography variant="h5" sx={{ mb: 3, fontWeight: 700, color: '#1A237E' }}>
                                Send us a Message
                            </Typography>
                            <Grid container spacing={3}>
                                <Grid item xs={12}>
                                    <TextField
                                        label="Full Name"
                                        name="name"
                                        fullWidth
                                        required
                                        value={formData.name}
                                        onChange={handleChange}
                                        sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }}
                                    />
                                </Grid>
                                <Grid item xs={12}>
                                    <TextField
                                        label="Email Address"
                                        name="email"
                                        type="email"
                                        fullWidth
                                        required
                                        value={formData.email}
                                        onChange={handleChange}
                                        sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }}
                                    />
                                </Grid>
                                <Grid item xs={12}>
                                    <TextField
                                        label="How can we help you?"
                                        name="message"
                                        multiline
                                        rows={4}
                                        fullWidth
                                        required
                                        value={formData.message}
                                        onChange={handleChange}
                                        sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }}
                                    />
                                </Grid>
                                <Grid item xs={12}>
                                    <Button 
                                        type="submit" 
                                        variant="contained" 
                                        disabled={loading}
                                        endIcon={!loading && <Send />}
                                        fullWidth
                                        sx={{ 
                                            py: 1.8,
                                            borderRadius: 2,
                                            fontWeight: 700,
                                            fontSize: '1rem',
                                            textTransform: 'none',
                                            bgcolor: '#1A237E', // Deep Blue
                                            color: '#FFD700', // Gold Text
                                            '&:hover': { 
                                                bgcolor: '#0D47A1',
                                                boxShadow: '0 8px 24px rgba(26, 35, 126, 0.3)'
                                            }
                                        }}
                                    >
                                        {loading ? <CircularProgress size={26} sx={{ color: '#FFD700' }} /> : 'Send Message'}
                                    </Button>
                                </Grid>
                            </Grid>
                        </form>
                    </Grid>
                </Grid>
            </Paper>
        </Container>
    );
};

export default ContactUs;